svg.script:
(function(){
  var s={
    input:false, physics:false, audio:false,
    inputEvent:false, physicsAction:false, moved:false,
    collision:false, neutralCollision:false,
    audioAction:false, audioPlay:false,
    local:false, meta:false
  };
  var x0=null, autoSent=false;

  function allLocal(){
    var scripts=[].slice.call(document.scripts||[]).filter(function(n){return !!n.src;});
    return scripts.length>=3 && scripts.every(function(n){
      var u=n.getAttribute('src')||'';
      return !/^https?:/i.test(u);
    });
  }

  function refresh(){
    s.input=!!window.SketsaInput;
    s.physics=!!window.SketsaPhysics;
    s.audio=!!window.SketsaAudio;
    s.local=allLocal();

    var im=document.querySelector('meta[name="sketsa-input-runtime"]');
    var pm=document.querySelector('meta[name="sketsa-physics-runtime"]');
    var am=document.querySelector('meta[name="sketsa-audio-runtime"]');
    s.meta=!!im && im.content.indexOf('0.8.0')===0 &&
           !!pm && pm.content.indexOf('0.9.6')===0 &&
           !!am && am.content.indexOf('0.8.2')===0;

    if(s.physics && x0===null){
      var b=window.SketsaPhysics.getBody && window.SketsaPhysics.getBody('e2e-player');
      if(b && b.position) x0=b.position.x;
    }
    if(s.physics && x0!==null){
      var b2=window.SketsaPhysics.getBody && window.SketsaPhysics.getBody('e2e-player');
      if(b2 && b2.position && b2.position.x > x0 + 0.15) s.moved=true;
    }

    var ok=s.input&&s.physics&&s.audio&&s.inputEvent&&s.physicsAction&&s.moved&&
           s.collision&&s.neutralCollision&&s.audioAction&&s.audioPlay&&s.local&&s.meta;
    var el=document.getElementById('e2e-status');
    if(el){
      el.textContent=(ok?'AUTOTEST PASS: ':'AUTOTEST: ')+
        'input='+s.input+', physics='+s.physics+', audio='+s.audio+
        ', inputEvent='+s.inputEvent+', physicsAction='+s.physicsAction+
        ', moved='+s.moved+', collision='+s.collision+
        ', neutral='+s.neutralCollision+', audioAction='+s.audioAction+
        ', audioPlay='+s.audioPlay+', local='+s.local+', meta='+s.meta;
      el.setAttribute('fill',ok?'#187a32':'#8a5a00');
    }
    return ok;
  }

  document.addEventListener('sketsa:input:event',function(e){
    var d=e.detail||{};
    var data=d.data||{};
    if(data.action==='move-right' && d.type==='down') s.inputEvent=true;
    refresh();
  });

  document.addEventListener('sketsa:physics:actionResult',function(e){
    var d=e.detail||{};
    if(d.ok && d.target==='e2e-player' && d.action==='applyImpulse') s.physicsAction=true;
    refresh();
  });

  document.addEventListener('sketsa:physics:collisionStart',function(e){
    var d=e.detail||{};
    if(d.eventId==='player-impact') s.collision=true;
    refresh();
  });

  document.addEventListener('sketsa:runtime:event',function(e){
    var d=e.detail||{};
    if(d.source==='physics' && d.type==='collisionStart' &&
       d.data && d.data.eventId==='player-impact') s.neutralCollision=true;
    refresh();
  });

  document.addEventListener('sketsa:audio:actionResult',function(e){
    var d=e.detail||{};
    if(d.ok && d.action==='play') s.audioAction=true;
    refresh();
  });

  document.addEventListener('sketsa:audio:event',function(e){
    var d=e.detail||{};
    if(d.type==='play') s.audioPlay=true;
    refresh();
  });

  var timer=setInterval(function(){
    refresh();
    if(!autoSent && s.input && s.physics && s.audio){
      autoSent=true;
      setTimeout(function(){
        window.dispatchEvent(new KeyboardEvent('keydown',{code:'ArrowRight',key:'ArrowRight',bubbles:true}));
        setTimeout(function(){
          window.dispatchEvent(new KeyboardEvent('keyup',{code:'ArrowRight',key:'ArrowRight',bubbles:true}));
        },80);
      },200);
    }
    if(refresh()) clearInterval(timer);
  },100);

  setTimeout(refresh,50);


  document.addEventListener('sketsa:input:event',function(e){
    var d=e.detail||{};
    var data=d.data||{};
    if(d.type==='down' && data.action==='jump'){
      document.dispatchEvent(new CustomEvent('sketsa:physics:action',{
        detail:{
          source:'e2e-manual',
          contractVersion:'1.0',
          requestId:'e2e-jump-'+Date.now(),
          action:'applyImpulse',
          target:'e2e-player',
          payload:{x:0,y:-2.5}
        }
      }));
    }
  });


  // Try to activate Web Audio immediately; if browser autoplay policy keeps
  // the context suspended, the first real user gesture unlocks it automatically.
  (function autoUnlockAudio(){
    var unlocked=false;
    function tryResume(){
      if(unlocked) return;
      try{
        if(window.SketsaAudio && typeof window.SketsaAudio.resume==='function'){
          var p=window.SketsaAudio.resume();
          if(p && typeof p.then==='function'){
            p.then(function(){
              try{
                if(!window.SketsaAudio.context || window.SketsaAudio.context.state==='running'){
                  unlocked=true;
                }
              }catch(_e){}
            }).catch(function(){});
          }
        }
      }catch(_e){}
    }

    // Immediate attempt for browsers that permit it.
    var immediate=setInterval(function(){
      if(window.SketsaAudio){
        clearInterval(immediate);
        tryResume();
      }
    },50);
    setTimeout(function(){ clearInterval(immediate); },3000);

    // Guaranteed user-gesture path: first keyboard/mouse/touch input.
    ['keydown','pointerdown','mousedown','touchstart'].forEach(function(type){
      window.addEventListener(type,tryResume,{capture:true,passive:true});
    });
  })();

  // Manual-play helper: keep applying a small horizontal force while a real
  // keyboard action is held. This uses only the public Input + Physics buses.
  (function manualPlayLoop(){
    function physicsAction(action, x, y){
      document.dispatchEvent(new CustomEvent('sketsa:physics:action',{
        detail:{
          source:'e2e-manual',
          contractVersion:'1.0',
          requestId:'e2e-manual-'+Date.now()+'-'+Math.random(),
          action:action,
          target:'e2e-player',
          payload:{x:x,y:y}
        }
      }));
    }
    function frame(){
      try{
        if(window.SketsaInput && window.SketsaPhysics){
          var left=window.SketsaInput.getAction && window.SketsaInput.getAction('move-left');
          var right=window.SketsaInput.getAction && window.SketsaInput.getAction('move-right');
          if(left && left.pressed) physicsAction('applyForce',-0.008,0);
          if(right && right.pressed) physicsAction('applyForce',0.008,0);
        }
      }catch(_e){}
      requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  })();
})();
